CREATE DATABASE IF NOT EXISTS hotelreservation_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE hotelreservation_db;
SET FOREIGN_KEY_CHECKS=0; DROP TABLE IF EXISTS login_attempts,password_resets,email_verifications,user_search_history,user_favorites,user_preferences,payments,room_amenities,room_images,reservations,rooms,room_types,amenities,notifications,activity_logs,hotel_settings,users; SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(50),address TEXT,role ENUM('CUSTOMER','ADMIN') NOT NULL DEFAULT 'CUSTOMER',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(email),INDEX(role,status));
CREATE TABLE room_types(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT,base_price DECIMAL(10,2) NOT NULL,max_guests INT NOT NULL,bed_type VARCHAR(80),size VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE rooms(id INT AUTO_INCREMENT PRIMARY KEY,room_number VARCHAR(20) NOT NULL UNIQUE,room_type_id INT NOT NULL,title VARCHAR(160) NOT NULL,description TEXT,price_per_night DECIMAL(10,2) NOT NULL,max_guests INT NOT NULL,bed_type VARCHAR(80),size VARCHAR(50),floor VARCHAR(20),status ENUM('AVAILABLE','OCCUPIED','MAINTENANCE','INACTIVE') NOT NULL DEFAULT 'AVAILABLE',featured TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(room_type_id),INDEX(status),FOREIGN KEY(room_type_id) REFERENCES room_types(id) ON DELETE RESTRICT);
CREATE TABLE user_preferences(user_id INT PRIMARY KEY,theme ENUM('light','dark') NOT NULL DEFAULT 'light',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE user_favorites(user_id INT NOT NULL,room_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,room_id),INDEX(room_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE);
CREATE TABLE user_search_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,check_in DATE NULL,check_out DATE NULL,guests INT NOT NULL DEFAULT 1,room_type_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(room_type_id) REFERENCES room_types(id) ON DELETE SET NULL);
CREATE TABLE room_images(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT NOT NULL,image_path VARCHAR(255) NOT NULL,is_primary TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE);
CREATE TABLE amenities(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description TEXT,icon VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE room_amenities(room_id INT NOT NULL,amenity_id INT NOT NULL,PRIMARY KEY(room_id,amenity_id),FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,FOREIGN KEY(amenity_id) REFERENCES amenities(id) ON DELETE CASCADE);
CREATE TABLE reservations(id INT AUTO_INCREMENT PRIMARY KEY,reservation_number VARCHAR(30) NOT NULL UNIQUE,user_id INT NOT NULL,room_id INT NOT NULL,check_in DATE NOT NULL,check_out DATE NOT NULL,guests INT NOT NULL,adults INT NOT NULL,children INT DEFAULT 0,nights INT NOT NULL,price_per_night DECIMAL(10,2) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,tax DECIMAL(10,2) NOT NULL DEFAULT 0,discount DECIMAL(10,2) NOT NULL DEFAULT 0,total_amount DECIMAL(10,2) NOT NULL,special_requests TEXT,status ENUM('PENDING','CONFIRMED','CHECKED_IN','CHECKED_OUT','CANCELLED','REJECTED','EXPIRED') DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),INDEX(room_id),INDEX(status),INDEX(check_in,check_out),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE RESTRICT);
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,reservation_id INT NOT NULL,payment_reference VARCHAR(60) UNIQUE,amount DECIMAL(10,2) NOT NULL,payment_method ENUM('CASH','GCASH','CREDIT_CARD','DEBIT_CARD','BANK_TRANSFER') NOT NULL DEFAULT 'CASH',payment_status ENUM('PENDING','PAID','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reservation_id) REFERENCES reservations(id) ON DELETE RESTRICT);
CREATE TABLE notifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,type VARCHAR(30) DEFAULT 'SYSTEM',is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,is_read),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE activity_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80),entity_id INT,description TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE hotel_settings(id INT AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(80) UNIQUE,setting_value TEXT);
